export type LessonContent = { title:string; objective:string; explanation:string; example:string; activity:string; check:string; failureMode:string; passCriterion:string; transfer:string; resourceIds:string[] };
const l = (title:string, explanation:string, example:string, activity:string, check:string, failureMode:string, passCriterion:string, transfer:string, ids:string): LessonContent => ({ title, objective:explanation.split('. ')[0]+'.', explanation, example, activity, check, failureMode, passCriterion, transfer, resourceIds:ids.split(' ') });
